// Built-in textured materials (Phase 17.1): texture images that ship with the app, like built-in templates, and
// the read-only presets that use them. The images are generated by `npm run materials:build` into
// server/builtin-materials/ and served for every house by the image file routes
// (spec/architecture/api.md#images). Their IDs use the reserved `builtinimg_` prefix, which still matches the
// ordinary ID pattern, so `house.json`, snapshots and Home Assistant accept them unchanged.
import type { SurfaceMaterialValue } from "../schemas/values";

/** The reserved image ID prefix of built-in textures. House uploads are always `img_…`. */
export const builtInImagePrefix = "builtinimg_";

export type BuiltInImage = Readonly<{
  id: string;
  name: string;
  /** File name in server/builtin-materials/ (PNG); its thumbnail is `<id>.thumb.webp`. */
  file: string;
  widthPx: number;
  heightPx: number;
  /** Physical size of one image repeat. */
  tileSizeMm: number;
  roughness: number;
  /** Name of the built-in preset that uses the image. */
  presetName: string;
  /** Built-in preset ID (reserved `builtin_` prefix). */
  presetId: string;
  /** glTF metallic factor of its preset (0 for all but metal coverings, Phase 19.1). */
  metallic: number;
}>;

const image = (
  key: string,
  name: string,
  presetName: string,
  tileSizeMm: number,
  roughness: number,
  metallic = 0,
): BuiltInImage => ({
  id: `${builtInImagePrefix}${key}`,
  name,
  file: `${builtInImagePrefix}${key}.png`,
  widthPx: 512,
  heightPx: 512,
  tileSizeMm,
  roughness,
  presetName,
  presetId: `builtin_${key}`,
  metallic,
});

/** Every built-in texture, in Presets-picker order. */
export const builtInImages: readonly BuiltInImage[] = [
  image("oakparquet", "Oak planks", "Oak parquet", 1600, 0.55),
  image("walnut", "Walnut planks", "Walnut", 1600, 0.5),
  image("ashplanks", "Pale ash planks", "Ash", 1600, 0.6),
  image("greytiles", "Grey stone tiles 60 cm", "Grey tiles", 1200, 0.35),
  image("whitetiles", "White tiles 15 cm", "White tiles", 600, 0.25),
  image("terracotta", "Terracotta tiles 30 cm", "Terracotta tiles", 1200, 0.75),
  image("slatetiles", "Slate tiles 60 × 30 cm", "Slate tiles", 1200, 0.6),
  image("granite", "Granite tiles 60 cm", "Granite", 1200, 0.3),
  image("decking", "Wood decking", "Decking", 1160, 0.8),
  image("lawngrass", "Lawn", "Lawn", 2400, 0.95),
  image("paving", "Sandstone paving", "Paving", 1200, 0.85),
  // Roof covering (Phase 19.1, owner 2026-11-18): plain light metal with standing seams every 500 mm.
  image("aluminium", "Aluminium standing-seam roofing", "Aluminium roofing", 2000, 0.4, 0.35),
];

export const isBuiltInImageId = (imageId: string): boolean => imageId.startsWith(builtInImagePrefix);

export const findBuiltInImage = (imageId: string): BuiltInImage | undefined =>
  builtInImages.find((candidate) => candidate.id === imageId);

/** The surface material of a built-in texture: untinted, its tile size and roughness, no rotation or offset. */
export const builtInTexturedMaterial = (
  texture: BuiltInImage,
  options: Readonly<{ rotationDeg?: number; tint?: readonly [number, number, number] }> = {},
): SurfaceMaterialValue => {
  const tint = options.tint ?? [1, 1, 1];
  return {
    pbrMetallicRoughness: {
      baseColorTexture: { imageId: texture.id },
      baseColorFactor: [tint[0], tint[1], tint[2], 1],
      roughnessFactor: texture.roughness,
      metallicFactor: texture.metallic,
    },
    extras: {
      homeplan: {
        tileSizeMm: { x: texture.tileSizeMm, y: texture.tileSizeMm },
        rotationDeg: options.rotationDeg ?? 0,
        offsetMm: { x: 0, y: 0 },
      },
    },
  };
};
